#include "ivory_distort.h"
#include <godot_cpp/core/math.hpp>
#include <algorithm>
using namespace godot;
void IvoryDistort::_bind_methods(){ ClassDB::bind_method(D_METHOD("apply","image","kind","amount"), &IvoryDistort::apply); BIND_ENUM_CONSTANT(LEAN);BIND_ENUM_CONSTANT(ARCH);BIND_ENUM_CONSTANT(SWELL);BIND_ENUM_CONSTANT(TWIST);BIND_ENUM_CONSTANT(PINCH);}
Ref<Image> IvoryDistort::apply(const Ref<Image>& src,int kind,double amount) const { if(src.is_null()) return Ref<Image>(); double t=Math::clamp(amount,-1.0,1.0); if(Math::abs(t)<1e-8) return src->duplicate(); int w=src->get_width(),h=src->get_height(); Ref<Image> out=Image::create(w,h,false,src->get_format()); for(int y=0;y<h;y++)for(int x=0;x<w;x++){ double u=(w>1?(2.0*x/(w-1)-1.0):0),v=(h>1?(2.0*y/(h-1)-1.0):0),sx=u,sy=v; switch(kind){case LEAN:sx=u+v*t;break;case ARCH:sy=v+(1-u*u)*t;break;case SWELL:sx=u/(1.0+(1-v*v)*t*0.8);break;case TWIST:{double a=-(1-v*v)*t*Math_PI*0.5,c=Math::cos(a),s=Math::sin(a);sx=u*c-v*s;sy=u*s+v*c;break;}case PINCH:{double r=Math::sqrt(u*u+v*v);double q=1.0-(1.0-Math::min(r,1.0)*Math::min(r,1.0))*t*0.45;sx=u/q;sy=v/q;break;}default:break;} double fx=(sx+1)*0.5*(w-1),fy=(sy+1)*0.5*(h-1); if(fx<0||fy<0||fx>w-1||fy>h-1){out->set_pixel(x,y,Color(0,0,0,0));continue;} int x0=(int)Math::floor(fx),y0=(int)Math::floor(fy),x1=std::min(x0+1,w-1),y1=std::min(y0+1,h-1); double ax=fx-x0,ay=fy-y0; Color a=src->get_pixel(x0,y0).lerp(src->get_pixel(x1,y0),ax),b=src->get_pixel(x0,y1).lerp(src->get_pixel(x1,y1),ax); out->set_pixel(x,y,a.lerp(b,ay)); } return out; }
